public List<List<Integer>> permute(int[] nums) {
    List<List<Integer>> result = new ArrayList<>();
    if (nums == null) {
        return result;
    }
    boolean[] used = new boolean[nums.length];
    List<Integer> current = new ArrayList<>();
    backtrack(nums, used, current, result);
    return result;
}

private void backtrack(int[] nums, boolean[] used, List<Integer> current, List<List<Integer>> result) {
    if (current.size() == nums.length) {
        result.add(new ArrayList<>(current));
        return;
    }
    for (int i = 0; i < nums.length; i++) {
        if (used[i]) {
            continue;
        }
        used[i] = true;
        current.add(nums[i]);
        backtrack(nums, used, current, result);
        current.remove(current.size() - 1);
        used[i] = false;
    }
}

public int findLargestSubstring(List<String> strings) {
    if (strings == null || strings.isEmpty()) {
        return 0;
    }
    String base = strings.get(0);
    int baseLen = base.length();
    int maxLen = 0;
    // Use a set to avoid duplicate substrings
    Set<String> seen = new HashSet<>();
    for (int i = 0; i < baseLen; i++) {
        for (int j = i + 1; j <= baseLen; j++) {
            String sub = base.substring(i, j);
            if (!seen.add(sub)) {
                continue; // already processed
            }
            int len = sub.length();
            if (len <= maxLen) {
                continue; // cannot beat current max
            }
            String rev = new StringBuilder(sub).reverse().toString();
            boolean ok = true;
            for (int k = 1; k < strings.size(); k++) {
                String s = strings.get(k);
                if (!(s.contains(sub) || s.contains(rev))) {
                    ok = false;
                    break;
                }
            }
            if (ok) {
                maxLen = len;
                // early exit if we found the longest possible
                if (maxLen == baseLen) {
                    return maxLen;
                }
            }
        }
    }
    return maxLen;
}

public static int countOilDeposits(char[][] grid) {
    if (grid == null || grid.length == 0) {
        return 0;
    }
    int rows = grid.length;
    int cols = grid[0].length;
    boolean[][] visited = new boolean[rows][cols];
    int deposits = 0;
    for (int r = 0; r < rows; r++) {
        for (int c = 0; c < grid[r].length; c++) {
            if (grid[r][c] == '@' && !visited[r][c]) {
                deposits++;
                dfs(r, c, grid, visited);
            }
        }
    }
    return deposits;
}

private static void dfs(int r, int c, char[][] grid, boolean[][] visited) {
    int rows = grid.length;
    int cols = grid[0].length;
    // 8-directional moves
    int[] dr = {-1, -1, -1, 0, 0, 1, 1, 1};
    int[] dc = {-1, 0, 1, -1, 1, -1, 0, 1};
    visited[r][c] = true;
    for (int k = 0; k < 8; k++) {
        int nr = r + dr[k];
        int nc = c + dc[k];
        if (nr >= 0 && nr < rows && nc >= 0 && nc < grid[nr].length) {
            if (grid[nr][nc] == '@' && !visited[nr][nc]) {
                dfs(nr, nc, grid, visited);
            }
        }
    }
}

