        return 0;
    }

    int count = 0;
    int prefixLength = prefix.length();

    for (String word : wordList) {
        if (word == null) {
            continue; // skip null entries
        }
        if (prefixLength == 0) {
            // Empty prefix matches all non-null words
            count++;
        } else if (word.length() >= prefixLength && word.startsWith(prefix)) {
            count++;
        }
    }

    return count;
}

