public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    try {
        if (n <= 0 || start == null || end == null || start.length != n || end.length != n) {
            return "cannot be travelled";
        }
        // Helper to convert coordinate array to string key
        java.util.function.Function<int[], String> coordToKey = coord -> {
            StringBuilder sb = new StringBuilder();
            for (int i = 0; i < coord.length; i++) {
                if (i > 0) sb.append(',');
                sb.append(coord[i]);
            }
            return sb.toString();
        };
        String startKey = coordToKey.apply(start);
        String endKey = coordToKey.apply(end);
        if (startKey.equals(endKey)) {
            return "can be travelled";
        }
        java.util.Map<String, java.util.List<String>> adj = new java.util.HashMap<>();
        if (paths != null) {
            for (int[] path : paths) {
                if (path == null || path.length != 2 * n) {
                    continue; // skip invalid path
                }
                int[] a = new int[n];
                int[] b = new int[n];
                System.arraycopy(path, 0, a, 0, n);
                System.arraycopy(path, n, b, 0, n);
                String aKey = coordToKey.apply(a);
                String bKey = coordToKey.apply(b);
                adj.computeIfAbsent(aKey, k -> new java.util.ArrayList<>()).add(bKey);
                adj.computeIfAbsent(bKey, k -> new java.util.ArrayList<>()).add(aKey);
            }
        }
        java.util.Queue<String> queue = new java.util.ArrayDeque<>();
        java.util.Set<String> visited = new java.util.HashSet<>();
        queue.add(startKey);
        visited.add(startKey);
        while (!queue.isEmpty()) {
            String cur = queue.poll();
            java.util.List<String> neighbors = adj.get(cur);
            if (neighbors == null) continue;
            for (String nb : neighbors) {
                if (visited.contains(nb)) continue;
                if (nb.equals(endKey)) {
                    return "can be travelled";
                }
                visited.add(nb);
                queue.add(nb);
            }
        }
        return "cannot be travelled";
    } catch (Exception e) {
        return "cannot be travelled";
    }
}

public static String convertDatesToWeekdays(String date) {
    if (date == null || date.trim().isEmpty()) {
        return "Invalid date";
    }
    try {
        java.time.format.DateTimeFormatter formatter =
                java.time.format.DateTimeFormatter.ofPattern("MM dd yyyy", java.util.Locale.ENGLISH);
        java.time.LocalDate localDate = java.time.LocalDate.parse(date.trim(), formatter);

        String monthName = localDate.getMonth()
                .getDisplayName(java.time.format.TextStyle.FULL, java.util.Locale.ENGLISH);
        int day = localDate.getDayOfMonth();
        int year = localDate.getYear();
        String weekday = localDate.getDayOfWeek()
                .getDisplayName(java.time.format.TextStyle.FULL, java.util.Locale.ENGLISH);

        return monthName + " " + day + ", " + year + " is a " + weekday;
    } catch (java.time.format.DateTimeParseException | java.time.DateTimeException e) {
        return "Invalid date";
    }
}

public int[] twoSum(int[] nums, int target) {
    if (nums == null) {
        throw new IllegalArgumentException("Input array cannot be null");
    }
    int n = nums.length;
    java.util.HashMap<Integer, Integer> map = new java.util.HashMap<>();
    for (int i = 0; i < n; i++) {
        int complement = target - nums[i];
        Integer prevIndex = map.get(complement);
        if (prevIndex != null) {
            return new int[]{prevIndex, i};
        }
        // Store the current number and its index
        map.put(nums[i], i);
    }
    throw new IllegalArgumentException("No two-sum solution exists for the given input");
}

public int search(int[] nums, int target) {
    if (nums == null || nums.length == 0) {
        return -1;
    }
    int left = 0;
    int right = nums.length - 1;
    while (left <= right) {
        int mid = left + (right - left) / 2;
        if (nums[mid] == target) {
            return mid;
        }
        // Determine which side is sorted
        if (nums[left] <= nums[mid]) { // left side is sorted
            if (nums[left] <= target && target < nums[mid]) {
                right = mid - 1;
            } else {
                left = mid + 1;
            }
        } else { // right side is sorted
            if (nums[mid] < target && target <= nums[right]) {
                left = mid + 1;
            } else {
                right = mid - 1;
            }
        }
    }
    return -1;
}

public double trimMean(int[] arr) {
    if (arr == null || arr.length == 0) {
        return 0.0;
    }
    int n = arr.length;
    int remove = n * 5 / 100; // floor of 5% of n
    // If remove is 0, just compute mean of all elements
    int start = remove;
    int end = n - remove;
    if (start >= end) {
        return 0.0;
    }
    int[] copy = arr.clone();
    java.util.Arrays.sort(copy);
    long sum = 0L;
    for (int i = start; i < end; i++) {
        sum += copy[i];
    }
    return (double) sum / (end - start);
}

public boolean canArrange(int[] arr, int k) {
    if (arr == null || k <= 0) {
        return false;
    }
    int n = arr.length;
    if (n % 2 != 0) {
        return false;
    }
    int[] count = new int[k];
    for (int num : arr) {
        int r = ((num % k) + k) % k;
        count[r]++;
    }
    // Remainder 0 must be even
    if (count[0] % 2 != 0) {
        return false;
    }
    // If k is even, remainder k/2 must also be even
    if (k % 2 == 0) {
        if (count[k / 2] % 2 != 0) {
            return false;
        }
    }
    // Check other remainders
    for (int r = 1; r <= k / 2; r++) {
        if (r == k - r) {
            continue; // already handled for even k
        }
        if (count[r] != count[k - r]) {
            return false;
        }
    }
    return true;
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    if (n <= 0 || edges == null || hasApple == null || hasApple.length != n) {
        return 0;
    }
    java.util.ArrayList<Integer>[] graph = new java.util.ArrayList[n];
    for (int i = 0; i < n; i++) {
        graph[i] = new java.util.ArrayList<Integer>();
    }
    for (int[] e : edges) {
        if (e == null || e.length != 2) continue;
        int u = e[0];
        int v = e[1];
        if (u < 0 || u >= n || v < 0 || v >= n) continue;
        graph[u].add(v);
        graph[v].add(u);
    }
    int[] parent = new int[n];
    java.util.Arrays.fill(parent, -1);
    java.util.Stack<Integer> stack = new java.util.Stack<Integer>();
    stack.push(0);
    parent[0] = -2;
    java.util.ArrayList<Integer> order = new java.util.ArrayList<Integer>();
    while (!stack.isEmpty()) {
        int node = stack.pop();
        order.add(node);
        java.util.List<Integer> neighbors = graph[node];
        for (int i = 0; i < neighbors.size(); i++) {
            int nei = neighbors.get(i);
            if (parent[nei] == -1) {
                parent[nei] = node;
                stack.push(nei);
            }
        }
    }
    int[] time = new int[n];
    for (int i = order.size() - 1; i >= 0; i--) {
        int node = order.get(i);
        if (node == 0) continue;
        int p = parent[node];
        if (time[node] > 0 || hasApple[node]) {
            time[p] += time[node] + 2;
        }
    }
    return time[0];
}

public String sortString(String s) {
    if (s == null || s.isEmpty()) {
        return "";
    }
    int[] count = new int[26];
    int total = 0;
    for (char c : s.toCharArray()) {
        if (c < 'a' || c > 'z') {
            // If the string contains characters outside 'a'-'z', treat them as is
            // by using a larger array or a map. For simplicity, we ignore them.
            continue;
        }
        count[c - 'a']++;
        total++;
    }
    StringBuilder result = new StringBuilder(total);
    while (total > 0) {
        // Ascending part
        int last = -1;
        for (int i = 0; i < 26; i++) {
            if (count[i] > 0) {
                result.append((char) ('a' + i));
                count[i]--;
                total--;
                last = i;
                break;
            }
        }
        if (last == -1) break; // no characters left
        while (true) {
            int next = -1;
            for (int i = last + 1; i < 26; i++) {
                if (count[i] > 0) {
                    next = i;
                    break;
                }
            }
            if (next == -1) break;
            result.append((char) ('a' + next));
            count[next]--;
            total--;
            last = next;
        }
        // Descending part
        last = -1;
        for (int i = 25; i >= 0; i--) {
            if (count[i] > 0) {
                result.append((char) ('a' + i));
                count[i]--;
                total--;
                last = i;
                break;
            }
        }
        if (last == -1) break;
        while (true) {
            int next = -1;
            for (int i = last - 1; i >= 0; i--) {
                if (count[i] > 0) {
                    next = i;
                    break;
                }
            }
            if (next == -1) break;
            result.append((char) ('a' + next));
            count[next]--;
            total--;
            last = next;
        }
    }
    return result.toString();
}

public boolean splitArraySameAverage(int[] nums) {
    if (nums == null || nums.length < 2) {
        return false;
    }
    int n = nums.length;
    int totalSum = 0;
    for (int num : nums) {
        totalSum += num;
    }
    // We only need to check k from 1 to n/2 because of symmetry
    for (int k = 1; k <= n / 2; k++) {
        if ((long) totalSum * k % n != 0) {
            continue;
        }
        int target = (int) ((long) totalSum * k / n);
        // dp[i] holds all achievable sums with i elements
        @SuppressWarnings("unchecked")
        java.util.HashSet<Integer>[] dp = new java.util.HashSet[k + 1];
        for (int i = 0; i <= k; i++) {
            dp[i] = new java.util.HashSet<>();
        }
        dp[0].add(0);
        for (int num : nums) {
            // iterate backwards to avoid using the same number multiple times
            for (int i = Math.min(k, n); i >= 1; i--) {
                for (int sum : dp[i - 1]) {
                    int newSum = sum + num;
                    if (newSum <= target) { // pruning: sums larger than target are useless
                        dp[i].add(newSum);
                    }
                }
            }
        }
        if (dp[k].contains(target)) {
            return true;
        }
    }
    return false;
}

public int minCostClimbingStairs(int[] cost) {
    // Handle null or empty input gracefully
    if (cost == null || cost.length == 0) {
        return 0;
    }
    int n = cost.length;
    // dp[i] represents the minimum cost to reach step i
    // We only need the last two values, so use two variables
    int prev2 = 0; // dp[i-2]
    int prev1 = 0; // dp[i-1]
    for (int i = 2; i <= n; i++) {
        int costFromPrev1 = prev1 + cost[i - 1];
        int costFromPrev2 = prev2 + cost[i - 2];
        int current = Math.min(costFromPrev1, costFromPrev2);
        prev2 = prev1;
        prev1 = current;
    }
    return prev1;
}

public int uniqueMorseRepresentations(String[] words) {
    if (words == null || words.length == 0) {
        return 0;
    }
    String[] morse = {".-","-...","-.-.","-..",".","..-.","--.","....","..",
                      ".---","-.-",".-..","--","-.","---",".--.","--.-",".-.",
                      "...","-","..-","...-",".--","-..-","-.--","--.."};
    java.util.Set<String> set = new java.util.HashSet<>();
    for (String word : words) {
        if (word == null) {
            continue;
        }
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < word.length(); i++) {
            char c = word.charAt(i);
            if (c >= 'a' && c <= 'z') {
                sb.append(morse[c - 'a']);
            } else if (c >= 'A' && c <= 'Z') {
                sb.append(morse[c - 'A']);
            } // ignore non-letter characters
        }
        set.add(sb.toString());
    }
    return set.size();
}

public boolean hasAllCodes(String s, int k) {
    if (s == null || k <= 0) {
        return false;
    }
    int n = s.length();
    // If k is too large, 2^k will exceed possible substrings
    if (k > 20) { // 2^20 = 1,048,576 > typical max n (1e5)
        return false;
    }
    int total = 1 << k;
    if (n < total) {
        return false;
    }
    int mask = total - 1;
    boolean[] seen = new boolean[total];
    int count = 0;
    int curr = 0;
    for (int i = 0; i < n; i++) {
        char c = s.charAt(i);
        if (c != '0' && c != '1') {
            return false; // invalid character
        }
        curr = ((curr << 1) & mask) | (c - '0');
        if (i >= k - 1) {
            if (!seen[curr]) {
                seen[curr] = true;
                count++;
                if (count == total) {
                    return true;
                }
            }
        }
    }
    return false;
}

