public static int singleNumber(int[] nums) {
    if (nums == null || nums.length == 0) {
        throw new IllegalArgumentException("Input array must not be null or empty.");
    }
    int result = 0;
    for (int i = 0; i < 32; i++) {
        int bitCount = 0;
        for (int num : nums) {
            bitCount += (num >> i) & 1;
        }
        if ((bitCount % 3) != 0) {
            result |= (1 << i);
        }
    }
    return result;
}

public static java.util.List<Integer> findSteppingNumbers(int low, int high) {
    java.util.List<Integer> result = new java.util.ArrayList<>();
    if (low > high) {
        return result;
    }
    if (low <= 0 && 0 <= high) {
        result.add(0);
    }
    java.util.Queue<Long> queue = new java.util.LinkedList<>();
    for (int i = 1; i <= 9; i++) {
        queue.add((long) i);
    }
    while (!queue.isEmpty()) {
        long num = queue.poll();
        if (num > high) {
            continue;
        }
        if (num >= low) {
            result.add((int) num);
        }
        int lastDigit = (int) (num % 10);
        int nextDigit1 = lastDigit + 1;
        if (nextDigit1 <= 9) {
            long nextNum = num * 10 + nextDigit1;
            if (nextNum <= high) {
                queue.add(nextNum);
            }
        }
        int nextDigit2 = lastDigit - 1;
        if (nextDigit2 >= 0) {
            long nextNum = num * 10 + nextDigit2;
            if (nextNum <= high) {
                queue.add(nextNum);
            }
        }
    }
    java.util.Collections.sort(result);
    return result;
}

public static int countDigitOne(int n) {
    if (n <= 0) {
        return 0;
    }
    long count = 0;
    long factor = 1;
    while (factor <= n) {
        long lower = n % factor;
        long cur = (n / factor) % 10;
        long higher = n / (factor * 10);
        if (cur == 0) {
            count += higher * factor;
        } else if (cur == 1) {
            count += higher * factor + lower + 1;
        } else {
            count += (higher + 1) * factor;
        }
        factor *= 10;
    }
    return (int) count;
}

public static boolean isPowerOfTwo(int n) {
    // A power of two must be a positive integer.
    if (n <= 0) {
        return false;
    }
    // Using the property that a power of two has only one bit set.
    // For any positive integer n, n & (n - 1) == 0 iff n is a power of two.
    return (n & (n - 1)) == 0;
}

public static int addDigits(int num) {
    if (num < 0) {
        throw new IllegalArgumentException("Input must be non-negative");
    }
    while (num >= 10) {
