        while (num > 0) {
            sum += num % 10;
            num /= 10;
        }
        num = sum;
    }
    return num;
}

public static int longestLine(int[][] mat) {
    if (mat == null || mat.length == 0) {
        return 0;
    }
    int m = mat.length;
    int n = mat[0] == null ? 0 : mat[0].length;
    if (n == 0) {
        return 0;
    }
    // Validate that all rows are non-null and have the same length
    for (int i = 0; i < m; i++) {
        if (mat[i] == null || mat[i].length != n) {
            return 0;
        }
    }

    int[][] left = new int[m][n];
    int[][] up = new int[m][n];
    int[][] diag = new int[m][n];
    int[][] anti = new int[m][n];
    int maxLen = 0;

    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            if (mat[i][j] == 1) {
                left[i][j] = (j > 0 ? left[i][j - 1] : 0) + 1;
                up[i][j] = (i > 0 ? up[i - 1][j] : 0) + 1;
                diag[i][j] = (i > 0 && j > 0 ? diag[i - 1][j - 1] : 0) + 1;
                anti[i][j] = (i > 0 && j < n - 1 ? anti[i - 1][j + 1] : 0) + 1;
                int cellMax = Math.max(Math.max(left[i][j], up[i][j]),
                                       Math.max(diag[i][j], anti[i][j]));
                if (cellMax > maxLen) {
                    maxLen = cellMax;
                }
            }
        }
    }
    return maxLen;
}

public static String addThousandSeparator(int n) {
    // Handle zero explicitly
    if (n == 0) {
        return "0";
    }

    boolean negative = n < 0;
    // Work with absolute value to simplify processing
    int absValue = Math.abs(n);
    String numberStr = Integer.toString(absValue);

    StringBuilder sb = new StringBuilder();
    int count = 0;
    // Iterate from the end of the string to the beginning
    for (int i = numberStr.length() - 1; i >= 0; i--) {
        sb.append(numberStr.charAt(i));
        count++;
        // Insert dot after every three digits, except if it's the last group
        if (count == 3 && i != 0) {
            sb.append('.');
            count = 0;
        }
    }

    // Reverse to get the correct order
    sb.reverse();

    // Prepend negative sign if necessary
    if (negative) {
        sb.insert(0, '-');
    }

    return sb.toString();
}

public static int squarePermutations(int[] A) {
    if (A == null) {
        throw new IllegalArgumentException("Input array cannot be null");
    }
    int n = A.length;
    if (n == 0) {
        return 1;
    }
    int maxVal = 0;
    for (int v : A) {
        if (v < 0) {
            throw new IllegalArgumentException("Array elements must be non-negative");
        }
        if (v > maxVal) {
            maxVal = v;
        }
    }
    int maxSum = maxVal * 2;
    boolean[] isSquare = new boolean[maxSum + 1];
    for (int i = 0; i * i <= maxSum; i++) {
        isSquare[i * i] = true;
    }

    int fullMask = (1 << n) - 1;
    long[][] dp = new long[1 << n][n];
    for (int i = 0; i < n; i++) {
        dp[1 << i][i] = 1;
    }

    for (int mask = 1; mask <= fullMask; mask++) {
        for (int last = 0; last < n; last++) {
            long cur = dp[mask][last];
            if (cur == 0) continue;
            for (int next = 0; next < n; next++) {
                if ((mask & (1 << next)) != 0) continue;
                if (isSquare[A[last] + A[next]]) {
                    dp[mask | (1 << next)][next] += cur;
                }
            }
        }
    }

    long result = 0;
    for (int last = 0; last < n; last++) {
        result += dp[fullMask][last];
    }
    return (int) result;
}

public static int largestRectangleArea(int[] heights) {
    if (heights == null || heights.length == 0) {
        return 0;
    }
    int n = heights.length;
    int[] stack = new int[n + 1];
    int top = -1;
    long maxArea = 0;
    for (int i = 0; i < n; i++) {
        while (top >= 0 && heights[stack[top]] >= heights[i]) {
            int height = heights[stack[top--]];
            int width = top >= 0 ? i - stack[top] - 1 : i;
            long area = (long) height * width;
            if (area > maxArea) {
                maxArea = area;
            }
        }
        stack[++top] = i;
    }
    while (top >= 0) {
        int height = heights[stack[top--]];
        int width = top >= 0 ? n - stack[top] - 1 : n;
        long area = (long) height * width;
        if (area > maxArea) {
            maxArea = area;
        }
    }
    return (int) maxArea;
}

public static int[] diagonalOrder(int[][] mat) {
    if (mat == null || mat.length == 0) {
        return new int[0];
    }
    int m = mat.length;
    int n = mat[0] != null ? mat[0].length : 0;
    if (n == 0) {
        return new int[0];
    }
    int[] result = new int[m * n];
    int idx = 0;
    for (int sum = 0; sum <= m + n - 2; sum++) {
        if (sum % 2 == 0) {
            int i = Math.min(sum, m - 1);
            for (; i >= 0; i--) {
                int j = sum - i;
                if (j < n && mat[i] != null) {
                    result[idx++] = mat[i][j];
                }
            }
        } else {
            int i = 0;
            int maxI = Math.min(sum, m - 1);
            for (; i <= maxI; i++) {
                int j = sum - i;
                if (j < n && mat[i] != null) {
                    result[idx++] = mat[i][j];
                }
            }
        }
    }
    return result;
}

